            array('id' => 7000054, 'type_intervention_id' => 4, 'localite_id' => 89, 'exercice_comptable_id' => 2, 'date_debut' => '2018-07-27', 'heure_debut' => '23:18:00', 'lieu' => 'Dans un champs', 'objet' => 'Feu d\'un champs', 'date_fin' => '2018-07-28', 'heure_fin' => '01:30:00', 'rapport_police' => '0', 'sapeur_id' => 2, 'stat_nb' => 1, 'sauve_personne' => 0, 'sauve_animaux' => 0, 'description' => 'Durant la journée, des personnes ont br&#251;lés des rumex. A 23h00, il y avait encore beaucoup de cendres incandescentes et de fumée. <br />Extinction à l\'aide des lances de premières interventions du VPI ainsi que du tonne. <br />Stève Simon est allé contrôler le 28.07.2018 au matin (09h00-10h00) e.o.', 'proprietaire' => 'Monsieur <br />Yerly Claude <br />Au Chésal 20<br />2864 Soulce<br />(à confirmer)', 'responsable' => '' . "" . '', 'degre' => 2, 'stat_federal_id' => 1, 'intervention_traitement_id' => 3, 'imputer' => 0),
